 for(const peer of lan.state?.players||[]){if(peer.id===lan.id)continue;const row=document.createElement('div'),name=document.createElement('strong'),hp=document.createElement('span'),track=document.createElement('i'),fill=document.createElement('b');name.textContent=peer.profile.name;hp.textContent=peer.downed?'DOWNED':`${Math.ceil(peer.hp)} HP`;fill.style.width=`${peer.hp/peer.maxHp*100}%`;track.append(fill);row.classList.toggle('downed',peer.downed);row.append(name,hp,track);panel.append(row)}
